"""A ledger of invoices."""


class InvoiceLedger:
    def __init__(self, invoices=()):
        self._invoices = list(invoices)

    def invoices(self):
        """Return the invoices held (a copy, so callers cannot change the ledger)."""
        return list(self._invoices)

    def add(self, invoice):
        """Add one invoice to the ledger."""
        self.invoices().append(invoice)

    def total(self):
        """Return the total due of the invoices held."""
        return sum(x.due for x in self._invoices)


def describe_invoice(invoice):
    """Return a one-line description of a invoice."""
    return "%s: %s" % (invoice.client, invoice.due)

